import React, { useState } from 'react';
import './HelperLogin.css';

const API_BASE = 'http://10.177.130.146:5000';

export default function HelperLogin({ onExistingHelper, onNewHelper }) {
  const [phone, setPhone] = useState('');
  const [focused, setFocused] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleContinue = async () => {
    const trimmed = phone.trim();
    if (!/^\d{10}$/.test(trimmed)) {
      setError('10 digit ka sahi mobile number daalo');
      return;
    }
    setError('');
    setLoading(true);

    try {
      const res = await fetch(`${API_BASE}/api/helpers/by-phone/${trimmed}`);

      if (res.status === 404) {
        onNewHelper(trimmed);
        return;
      }
      if (!res.ok) {
        setError('Kuch galat ho gaya, dobara try karo');
        setLoading(false);
        return;
      }

      const helperData = await res.json();
      localStorage.setItem('atakGayeHelper', JSON.stringify(helperData));
      onExistingHelper(helperData);
    } catch (err) {
      console.error('Login check failed:', err);
      setError('Backend se connect nahi ho paya');
      setLoading(false);
    }
  };

  return (
    <div className="login-screen">
      <div className="login-logo"><span>A</span></div>

      <h1 className="login-title">Atak Gaye Ke Saath Jud Jao</h1>
      <p className="login-subtitle">Nearby customers ki madad karo aur kamao</p>

      <div className="login-illo">
        <svg viewBox="0 0 300 220" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
          <rect x="0" y="176" width="300" height="30" fill="#F2F0EC" />
          <line x1="0" y1="176" x2="300" y2="176" stroke="#E5E2DC" strokeWidth="2" />

          <g transform="translate(190,120)">
            <rect x="0" y="20" width="70" height="26" rx="8" fill="#1A1A1A" />
            <path d="M8,20 L18,4 Q21,0 27,0 L52,0 Q58,0 61,5 L68,20 Z" fill="#1A1A1A" />
            <rect x="21" y="4" width="28" height="14" rx="3" fill="#DCE6FF" />
            <circle cx="14" cy="48" r="8" fill="#333" />
            <circle cx="58" cy="48" r="8" fill="#333" />
          </g>

          <g transform="translate(40,116)">
            <path d="M8,54 L16,32 Q19,24 28,24 L54,24 L64,44 L64,54 Z" fill="#FF6A3D" />
            <g className="wheel-spin">
              <circle cx="14" cy="56" r="11" fill="#1A1A1A" />
              <circle cx="14" cy="56" r="4" fill="#94A3B8" />
            </g>
            <g className="wheel-spin">
              <circle cx="66" cy="56" r="11" fill="#1A1A1A" />
              <circle cx="66" cy="56" r="4" fill="#94A3B8" />
            </g>
            <path d="M30,24 Q26,6 36,-3 Q42,-8 48,-3 L45,8 L37,24 Z" fill="#FF6A3D" />
            <circle cx="40" cy="-11" r="12" fill="#FF8C00" />
          </g>

          <g transform="translate(150,54)">
            <circle className="pulse-ring" cx="12" cy="12" r="12" fill="#FF6A3D" />
            <path d="M12,0 C5,0 0,5 0,12 C0,21 12,35 12,35 C12,35 24,21 24,12 C24,5 19,0 12,0 Z" fill="#FF6A3D" />
            <circle cx="12" cy="12" r="5" fill="#fff" />
          </g>
        </svg>
      </div>

      <div className="login-card">
        <h2 className="login-card-title">Helper Login</h2>
        <p className="login-card-sub">Shuru karne ke liye apna mobile number daalo</p>

        <div className={`phone-input ${focused ? 'focused' : ''}`}>
          <span className="phone-prefix">IN +91</span>
          <input
            value={phone}
            onChange={(e) => setPhone(e.target.value)}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            placeholder="Mobile number"
            inputMode="numeric"
            maxLength={10}
            disabled={loading}
          />
        </div>

        {error && <div className="login-error">{error}</div>}

        <button className="continue-btn squish" onClick={handleContinue} disabled={loading}>
          {loading ? 'Check ho raha hai...' : 'Continue'}
        </button>
      </div>
    </div>
  );
}
